.metric .value { display: block; font-size: 21px; font-weight: 600; line-height: 1.3; overflow-wrap: anywhere; }
.metric .detail { display: block; margin-top: 5px; font-size: 11px; color: var(--muted); }
.definition { display: grid; grid-template-columns: minmax(115px, .7fr) minmax(0, 1.8fr); gap: 9px 15px; margin: 0; }
.definition dt { color: var(--muted); font-size: 12px; }
.definition dd { margin: 0; overflow-wrap: anywhere; }
.table-wrap { width: 100%; overflow: auto; border: 1px solid var(--line); }
table { border-collapse: collapse; width: 100%; text-align: left; font-size: 12px; }
th { font-weight: 600; white-space: nowrap; background: #f5f5f2; color: #505050; }
th, td { border-bottom: 1px solid var(--line); padding: 10px 12px; vertical-align: top; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr.selected { background: #ececea; }
td.long { max-width: 450px; overflow-wrap: anywhere; }
td.nowrap { white-space: nowrap; }
table button, table .button { font-size: 12px; padding: 3px 8px; min-height: 28px; }
.file-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 5px; }
.file-list button { width: 100%; display: grid; gap: 3px; justify-content: stretch; text-align: left; padding: 9px 10px; overflow-wrap: anywhere; font-size: 12px; }
.file-list button[aria-current=true] { background: #e9e9e6; border-color: #777; }
.file-list small { font-weight: normal; font-size: 10px; }
.notice { background: #fff; border: 1px solid #999; border-left: 4px solid #444; margin: 15px 28px 0; padding: 12px 15px; overflow-wrap: anywhere; }
.notice .button-row { margin-top: 10px; }
.notice.issue { border-left-color: #111; background: #eeeeeb; }
.inline-note { background: #f3f3f0; border: 1px solid var(--line); padding: 12px; font-size: 12px; overflow-wrap: anywhere; }
.empty { padding: 25px 18px; background: #f8f8f6; color: var(--muted); border: 1px dashed #c7c7c1; text-align: left; }
.status-line { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; margin-bottom: 14px; }
.rule { border: 0; border-top: 1px solid var(--line); margin: 18px 0; }
.overflow-text { max-height: 370px; overflow: auto; padding: 14px; border: 1px solid var(--line); background: #f8f8f6; }
.code-label { display: flex; justify-content: space-between; gap: 10px; align-items: baseline; margin-bottom: 7px; }
.code-label label { margin: 0; }
.pagination { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 14px; }
details { border: 1px solid var(--line); border-radius: 2px; background: #fff; }
summary { padding: 11px 13px; cursor: pointer; font-size: 12px; font-weight: 600; }
details > .details-body { padding: 0 13px 13px; }
footer { display: flex; justify-content: space-between; gap: 16px; padding: 14px 28px; border-top: 1px solid var(--line); background: #f9f9f7; color: var(--muted); font-size: 11px; }
dialog { max-width: 490px; width: calc(100% - 36px); padding: 24px; border: 1px solid #777; border-radius: 3px; color: var(--ink); }
dialog::backdrop { background: #0006; }
@media (max-width: 1000px) {
  .grid.main-aside { grid-template-columns: minmax(0, 1fr); }
  .metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .form-grid.three { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 680px) {
  .masthead { padding: 18px 15px; align-items: flex-start; flex-direction: column; gap: 12px; }
  .masthead-state { max-width: 100%; justify-content: flex-start; }
  h1 { font-size: 20px; }
  .toolbar { padding: 12px 15px; flex-direction: column; align-items: stretch; }
  .toolbar .button-row { display: grid; grid-template-columns: 1fr 1fr; }
  .tabs { padding: 0 10px; }
  .tabs button { padding: 12px 9px 10px; }
  main { padding: 18px 15px 26px; }
  .notice { margin: 12px 15px 0; }
  .card { padding: 15px; }
  .grid.two, .grid.aside-main, .form-grid, .form-grid.three { grid-template-columns: minmax(0, 1fr); }
  .section-head, .card-head { flex-direction: column; gap: 12px; }
  .metrics { gap: 9px; }
