  .metric .value { font-size: 19px; }
  .definition { grid-template-columns: minmax(95px, .7fr) minmax(0, 1.6fr); gap: 8px; }
  textarea.code.application-code { min-height: 360px; }
  .file-list { max-height: 200px; overflow: auto; }
