      '--expected-revision', '--action', '--policy'].includes(rest[i]) || values.has(rest[i]) ||
      typeof rest[i + 1] !== 'string' || !rest[i + 1]) throw new TypeError(USAGE);
    values.set(rest[i], rest[i + 1]);
